 body=panel('What we can check',p(t['facts'])+links(t['sources']))+panel('Choices and tradeoffs',opts(t['choices']))+panel('A practical public voice',p(t['action']))+panel('related solutions',p(t['connection'])+links(t['related']))+panel('Status and sources',p('Checked 3 October 2026. Source dates and jurisdictions remain attached to the evidence. These are choices for public discussion, not an adopted party platform.'))+links([(f'twinkle-{t["slug"]}.html',f'Twinkle {n:02d}: {t["label"]}')])
 save(t['slug'],page(t['title'],t['sub'],body))
 prev='twinkle-ancient-aliens' if n==31 else 'twinkle-'+topics[n-32]['slug']
 nxt='twinkle-tolls' if n==46 else 'twinkle-'+topics[n-30]['slug']
 seed=panel('The everyday question',p(t['sub']))+panel('The one-breath drop',p('“'+t['drop']+'”'))+panel('The serious room underneath',p(t['facts'])+links(t['sources'])+links([(t['slug']+'.html','Compare the choices and take part')]))+f'<div class="next-trail"><a class="button button-secondary" href="{prev}.html">Previous Twinkle</a><a class="button button-secondary" href="twinkle.html#seeds">All Twinkles</a><a class="button button-secondary" href="{nxt}.html">Next Twinkle</a><a class="button button-primary" href="{t["slug"]}.html">Follow-through room</a></div>'
